  "الشيخ سمير مصطفى": {en:"Sheikh Samir Mustafa",fr:"Cheikh Samir Moustapha",id:"Syekh Samir Musthafa",ur:"شیخ سمیر مصطفیٰ",bn:"শায়খ সামির মুস্তফা",tr:"Şeyh Semir Mustafa"},
