  "الشيخ عبد الرزاق البدر": {en:"Sheikh Abdulrazzaq al-Badr",fr:"Cheikh Abdulrazzaq al-Badr",id:"Syekh Abdulrazzaq al-Badr",ur:"شیخ عبد الرزاق البدر",bn:"শায়খ আব্দুর রাযযাক আল-বদর",tr:"Şeyh Abdurrazzak el-Bedr"},
  "الشيخ عبد السلام الشويعر": {en:"Sheikh Abdul-Salam al-Shuway'ir",fr:"Cheikh Abdul-Salam al-Shuway'ir",id:"Syekh Abdul-Salam asy-Syuwa'ir",ur:"شیخ عبد السلام الشویعر",bn:"শায়খ আব্দুস সালাম আশ-শুওয়াইর",tr:"Şeyh Abdüsselam eş-Şuvey'ir"},
  "الشيخ عثمان الخميس": {en:"Sheikh Uthman al-Khamees",fr:"Cheikh Othman al-Khamis",id:"Syekh Utsman al-Khamis",ur:"شیخ عثمان الخمیس",bn:"শায়খ উসমান আল-খামিস",tr:"Şeyh Osman el-Hamîs"},
  "الشيخ محمد الغليظ": {en:"Sheikh Muhammad al-Ghaleez",fr:"Cheikh Muhammad al-Ghaliz",id:"Syekh Muhammad al-Ghaliz",ur:"شیخ محمد الغلیظ",bn:"শায়খ মুহাম্মদ আল-গালিজ",tr:"Şeyh Muhammed el-Galîz"},
